(function(){
 const KEY='nawaf-hq-v3',MODE='real-workforce-v1',API='/api/gemini';
 const get=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch{return null}},put=s=>localStorage.setItem(KEY,JSON.stringify(s));
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const now=()=>new Date().toISOString(),name=(s,id)=>id==='nawaf'?'نواف':(s.employees||[]).find(e=>e.id===id)?.name||id;
 function ensure(s){if(!s)return s;s.discussions=s.discussions||[];if(!s.discussions.find(r=>r.id==='company'))s.discussions.unshift({id:'company',type:'COMPANY',title:'مجلس الشركة',participants:['nawaf','sara','omar','lian','noura'],messages:[]});return s}
 function modal(html){let m=document.querySelector('#modal'),d=document.querySelector('#dialog');if(!m||!d)return;d.innerHTML='<div class="dialog-wide board-dialog">'+html+'</div>';m.classList.add('open');m.onclick=e=>{if(e.target===m)m.classList.remove('open')}}
 function rooms(s){return [s.discussions.find(r=>r.id==='company'),...(s.discussions||[]).filter(r=>r.id!=='company')].filter(Boolean)}
 async function health(s){try{let r=await fetch(API,{cache:'no-store'}),j=await r.json();let ai=(s.integrations||[]).find(i=>i.id==='ai-model');if(ai){ai.status=j.ok&&j.configured?'CONNECTED':'NOT_CONNECTED';ai.mode=j.ok&&j.configured?'SERVER_SIDE':'DISABLED';ai.provider='Gemini';ai.model=j.model||null;ai.checkedAt=now();put(s)}return !!(j.ok&&j.configured)}catch{return false}}
 function context(s,room){let project=room.project?(s.projects||[]).find(p=>p.id===room.project):null;return {room:{id:room.id,title:room.title,type:room.type,project:room.project||null},project:project?{id:project.id,name:project.name,status:project.status,progress:project.progress}:null,tasks:(s.tasks||[]).filter(t=>!room.project||t.project===room.project).slice(-8),reports:(s.reports||[]).filter(r=>!room.project||r.project===room.project).slice(-5).map(r=>({id:r.id,title:r.title,status:r.status,summary:r.summary||r.text||''})),artifacts:(s.artifacts||[]).filter(a=>!room.project||a.project===room.project).slice(-5).map(a=>({id:a.id,title:a.title,status:a.status,findings:a.findings||[],evidence:a.evidence||[]}))}}
 const SYSTEM=`أنت محرك القوى العاملة الحقيقي لشركة NAWAF HQ. الرئيس التنفيذي نواف. الموظفون: سارة المديرة العامة، عمر باحث ومنفذ تقني، ليان UX/Product، نورة QA/Data. لا تدّع تنفيذ أي فعل خارجي أو قراءة مصدر أو إنجاز لم يحدث فعلاً. استخدم فقط السياق والأدلة المرسلة. فرّق بين التحليل الداخلي والتنفيذ الخارجي. ممنوع أي إنفاق أو خدمة مدفوعة بدون موافقة نواف الصريحة. تغييرات المحتوى الديني في مُعِين تحتاج مراجعة نواف. أعد JSON فقط بالشكل {"messages":[{"author":"sara|omar|lian|noura","text":"...","type":"AI_INTERNAL_ANALYSIS"}],"proposals":[{"title":"...","owner":"sara|omar|lian|noura","reason":"...","needsApproval":false}],"summary":"..."}. اجعل الحوار طبيعيًا ومفيدًا ومختصرًا، ويمكن للموظفين الاختلاف واقتراح فحص إضافي. لا تخترع أدلة.`;
 async function runAI(roomId,trigger){let s=ensure(get()),room=s?.discussions.find(r=>r.id===roomId);if(!s||!room)return;let ok=await health(s);if(!ok){alert('Gemini غير متصل حاليًا. تأكد أن GEMINI_API_KEY موجود في Vercel وأن آخر Deployment جاهز.');return}let recent=(room.messages||[]).slice(-16).map(m=>({role:m.author==='nawaf'?'user':'model',text:`${name(s,m.author)}: ${m.text}`}));recent.push({role:'user',text:'سياق العمل الموثق:\n'+JSON.stringify(context(s,room))+'\nسبب تشغيل المجلس: '+trigger});setBusy(true);try{let r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({system:SYSTEM,messages:recent})}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'AI_FAILED');let out=j.result||{},stamp=Date.now();(out.messages||[]).slice(0,6).forEach((m,i)=>{if(!['sara','omar','lian','noura'].includes(m.author)||!m.text)return;room.messages.push({id:`ai-${stamp}-${i}`,author:m.author,text:String(m.text),createdAt:now(),type:m.type||'AI_INTERNAL_ANALYSIS',links:{}})});s.proposals=s.proposals||[];(out.proposals||[]).slice(0,5).forEach((p,i)=>s.proposals.push({id:`proposal-${stamp}-${i}`,title:String(p.title||'اقتراح'),owner:['sara','omar','lian','noura'].includes(p.owner)?p.owner:'sara',reason:String(p.reason||''),needsApproval:!!p.needsApproval,status:'PROPOSED',createdAt:now(),source:'GEMINI_DISCUSSION',discussion:room.id}));if(out.summary)room.messages.push({id:`summary-${stamp}`,author:'sara',text:'خلاصة المجلس: '+String(out.summary),createdAt:now(),type:'AI_SUMMARY',links:{}});s.activities.unshift({id:`audit-${stamp}`,text:'انعقد نقاش AI داخلي حقيقي في '+room.title,kind:'AI_INTERNAL',createdAt:now(),links:{discussion:room.id}});put(s);openBoard(room.id)}catch(e){console.error(e);alert('تعذر تشغيل مجلس AI الآن. لم يتم تسجيل أي إنجاز وهمي.')}finally{setBusy(false)}}
 function setBusy(v){let b=document.querySelector('#board-ai');if(b){b.disabled=v;b.textContent=v?'الموظفون يناقشون الآن…':'تشغيل نقاش الموظفين'}}
 function openBoard(roomId='company'){let s=ensure(get());if(!s||s.meta?.mode!==MODE)return;let rs=rooms(s),room=rs.find(r=>r.id===roomId)||rs[0],ai=(s.integrations||[]).find(i=>i.id==='ai-model'),connected=ai?.status==='CONNECTED';const msgs=(room.messages||[]).map(m=>`<article class="board-msg ${m.author==='nawaf'?'ceo':''}"><header><b>${esc(name(s,m.author))}</b><time>${new Date(m.createdAt).toLocaleString('ar-SA',{hour:'2-digit',minute:'2-digit'})}</time></header><p>${esc(m.text)}</p>${links(m)}</article>`).join('')||'<div class="board-empty">ما فيه نقاش إلى الآن. اكتب توجيهك، وبعد اتصال Gemini يمكن للموظفين مناقشته فعليًا.</div>';modal(`<div class="board-head"><div><span class="eyebrow">COMPANY DISCUSSIONS</span><h2>${esc(room.title)}</h2><p>نقاشات مرتبطة بالشغل والأدلة، مو رسائل تمثيلية.</p></div><button class="dialog-close" id="board-close">إغلاق</button></div><div class="board-layout"><aside class="board-rooms"><b>الغرف</b>${rs.map(r=>`<button data-room="${esc(r.id)}" class="${r.id===room.id?'active':''}">${esc(r.title)}<small>${(r.messages||[]).length} رسالة</small></button>`).join('')}</aside><main class="board-main"><div class="board-truth ${connected?'connected':'offline'}"><i></i><span>${connected?'Gemini متصل — نقاشات AI داخلية حقيقية':'جارٍ التحقق من Gemini…'}</span></div><section class="board-messages">${msgs}</section><form id="board-form"><textarea required placeholder="اكتب للفريق أو ادخل في النقاش..."></textarea><button class="primary">إرسال للمجلس</button></form><div class="board-tools"><button id="board-ai">تشغيل نقاش الموظفين</button><button id="board-evidence">استخراج نقاط من النتائج الحقيقية</button><button id="board-command">توجيه عمل جديد</button></div></main></div>`);document.querySelector('#board-close').onclick=()=>document.querySelector('#modal').classList.remove('open');document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>openBoard(b.dataset.room));document.querySelector('#board-form').onsubmit=e=>{e.preventDefault();let text=e.target.querySelector('textarea').value.trim();if(!text)return;s=ensure(get());let r=s.discussions.find(x=>x.id===room.id);r.messages.push({id:'msg-'+Date.now(),author:'nawaf',text,createdAt:now(),type:'CEO_MESSAGE',links:{}});s.activities.unshift({id:'audit-'+Date.now(),text:'نواف أرسل رسالة في '+r.title,kind:'REAL',createdAt:now(),links:{discussion:r.id}});put(s);openBoard(r.id)};document.querySelector('#board-ai').onclick=()=>runAI(room.id,'نواف طلب من الموظفين مناقشة آخر سياق ورسائل المجلس');document.querySelector('#board-evidence').onclick=()=>evidence(room.id);document.querySelector('#board-command').onclick=()=>{document.querySelector('#modal').classList.remove('open');setTimeout(()=>{[...document.querySelectorAll('button')].find(x=>x.textContent.includes('بسم الله')||x.textContent.includes('أعطِ توجيهًا'))?.click()},50)};health(s).then(ok=>{let el=document.querySelector('.board-truth span');if(el)el.textContent=ok?'Gemini متصل — نقاشات AI داخلية حقيقية':'Gemini غير متصل — لن نولّد ردودًا وهمية';let box=document.querySelector('.board-truth');if(box)box.classList.toggle('connected',ok)})}
 function links(m){let a=[];if(m.links?.report)a.push('تقرير');if(m.links?.artifact)a.push('مخرج');if(m.links?.task)a.push('مهمة');return a.length?'<footer>مرتبط بـ: '+a.join(' · ')+'</footer>':''}
 function evidence(roomId){let s=ensure(get()),r=s.discussions.find(x=>x.id===roomId),pid=r?.project,arts=(s.artifacts||[]).filter(a=>!pid||a.project===pid),reps=(s.reports||[]).filter(a=>!pid||a.project===pid);if(!arts.length&&!reps.length){alert('ما فيه نتائج حقيقية مرتبطة بهذه الغرفة إلى الآن.');return}let latest=arts.at(-1),rep=reps.at(-1),facts=latest?.findings||[],text=facts.length?'نقاط مثبتة من آخر مخرج:\n• '+facts.slice(0,4).join('\n• '):'يوجد تقرير حقيقي جاهز للنقاش: '+rep.title;r.messages.push({id:'msg-'+Date.now(),author:latest?.author||rep?.author||'noura',text,createdAt:now(),type:'EVIDENCE_DISCUSSION',links:{artifact:latest?.id,report:rep?.id}});s.activities.unshift({id:'audit-'+Date.now(),text:'أضيفت نقاط نقاش من نتيجة عمل محفوظة',kind:'REAL',createdAt:now(),links:{discussion:r.id,artifact:latest?.id,report:rep?.id}});put(s);openBoard(roomId)}
 function bind(){document.querySelectorAll('button').forEach(b=>{if(b.dataset.boardBound)return;if(b.textContent.includes('مجلس الشركة')){b.dataset.boardBound='1';b.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();openBoard('company')},true)}})}
 const mo=new MutationObserver(()=>{clearTimeout(window.__boardBind);window.__boardBind=setTimeout(bind,60)});mo.observe(document.documentElement,{subtree:true,childList:true});document.readyState==='loading'?document.addEventListener('DOMContentLoaded',bind):bind();window.NawafCompanyBoard={open:openBoard,runAI};
})();